mapper.sql:
WHERE s."利用者アカウントID" = #{accountId}

    AND s."学習状態" = #{learnState}


    AND w."JLPTレベル" = #{jlpt}

mapper.select:
SELECT 


 ORDER BY s."最終学習日時" DESC NULLS LAST, s."単語ID" ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.sql:
WHERE k."利用者アカウントID" = #{accountId}

    AND k."テスト種別" = #{testType}


    AND k."技能区分" ILIKE '%' || #{skill} || '%'

mapper.insert:
INSERT INTO public."JPN_学習状況情報" (
    "利用者アカウントID", "単語ID", "学習状態", "登録者アカウントID", "登録元コード"
) VALUES (
    #{accountId}, #{wordId}, 'LEARNING', #{accountId}, 'APP'
)
ON CONFLICT ("利用者アカウントID", "単語ID") DO NOTHING

mapper.select:
SELECT k."単語ID", w."見出し語", w."読み", k."テスト種別", k."技能区分", k."学習状態", k."習得度",
       k."回答回数", k."正解回数", k."不正解回数", k."連続正解回数", k."最大連続正解回数",
       k."最終判定", k."最終学習日時", k."次回復習日時"
  FROM public."JPN_技能習得情報" k
  JOIN public."JPN_単語情報" w ON w."単語ID" = k."単語ID"
 WHERE k."利用者アカウントID" = #{accountId}
   AND k."単語ID" = #{wordId}
   AND k."テスト種別" = #{testType}
   AND k."技能区分" = #{skillCode}

SELECT round(avg(k."習得度"), 2)
  FROM public."JPN_技能習得情報" k
 WHERE k."利用者アカウントID" = #{accountId}
   AND k."単語ID" = #{wordId}
